// Part of an order service for a grocery delivery app.
// Getters: getStatus() returns a String such as "PAID" or "CANCELLED",
// getCity() returns a String (it can be null for old orders),
// getAmount() returns an int amount in rupees.

public class OrderService {
    private List<Order> orders = new ArrayList<>();

    // Remove cancelled orders, then return the average order value
    // (in rupees, with paise) for orders in the given city.
    public double cleanAndAverage(String cityFilter) {
        int total = 0;
        for (Order o : orders) {
            if (o.getStatus() == "CANCELLED") {
                orders.remove(o);
            }
        }
        for (Order o : orders) {
            if (o.getCity().equals(cityFilter)) {
                total += o.getAmount();
            }
        }
        return total / orders.size();
    }
}
